import scala.collection.mutable.ArrayBuffer

def inorderTraversal(root: TreeNode): Array[Int] = {
  val result = ArrayBuffer.empty[Int]

  def traverse(node: TreeNode): Unit = {
    if (node == null) {
      return
    }

    traverse(node.left)
    result += node.value
    traverse(node.right)
  }

  traverse(root)
  result.toArray
}

