def hasPathSum(node: TreeNode, target: Int): Boolean = {
  if (node == null) {
    return false
  }

  val isLeaf = node.left == null && node.right == null
  if (isLeaf) {
    return node.value == target
  }

  val remainingTarget = target - node.value

  hasPathSum(node.left, remainingTarget) ||
    hasPathSum(node.right, remainingTarget)
}

