import scala.collection.mutable.ArrayBuffer
import scala.collection.mutable.Queue

def levelOrder(root: TreeNode): Array[Array[Int]] = {
  if (root == null) {
    return Array.empty[Array[Int]]
  }

  val result = ArrayBuffer.empty[Array[Int]]
  val queue = Queue(root)

  while (queue.nonEmpty) {
    val currentLevelSize = queue.size
    val currentLevelValues = ArrayBuffer.empty[Int]

    for (_ <- 0 until currentLevelSize) {
      val currentNode = queue.dequeue()
      currentLevelValues += currentNode.value

      if (currentNode.left != null) {
        queue.enqueue(currentNode.left)
      }
      if (currentNode.right != null) {
        queue.enqueue(currentNode.right)
      }
    }

    result += currentLevelValues.toArray
  }

  result.toArray
}

