def lowestCommonAncestor(root: TreeNode, firstValue: Int, secondValue: Int): TreeNode = {
  var currentNode = root

  while (currentNode != null) {
    if (firstValue < currentNode.value && secondValue < currentNode.value) {
      currentNode = currentNode.left
    } else if (firstValue > currentNode.value && secondValue > currentNode.value) {
      currentNode = currentNode.right
    } else {
      return currentNode
    }
  }

  null
}

def isBalanced(root: TreeNode): Boolean = {
  def heightOrInvalid(node: TreeNode): Int = {
    if (node == null) {
      return 0
    }

    val leftHeight = heightOrInvalid(node.left)
    if (leftHeight == -1) {
      return -1
    }

    val rightHeight = heightOrInvalid(node.right)
    if (rightHeight == -1) {
      return -1
    }

    if (math.abs(leftHeight - rightHeight) > 1) {
      return -1
    }

    1 + math.max(leftHeight, rightHeight)
  }

  heightOrInvalid(root) != -1
}

